function L = phase5b_source_ledger(varargin)
%PHASE5B_SOURCE_LEDGER  Transcribed protection-source table (Phase-5b Task C1).
%   L = PHASE5B_SOURCE_LEDGER() returns struct array with fields:
%     .source_id,.claim,.value,.locator,.class
%   class in SOURCE-BACKED/DERIVED/USER_ASSERTED_PENDING_DOC/ENGINEERING_ASSUMPTION/MISSING.
%   Only the 4 Siemens-settings rows carry USER_ASSERTED_PENDING_DOC.
%   All errors 'phase5b'-prefixed.
if nargin ~= 0
    error('phase5b_source_ledger:args', 'phase5b_source_ledger takes no arguments.');
end
M = 'Ashuganj_South_Final_Master_Data_and_Assumptions (1).md:';
R = 'REV3_PROGRESS.md:';
P67 = 'Generator Data_South.pdf:pp.6-7';
PEND = 'Generator Data_South.pdf:pp.8-39-PENDING-DOC-INGEST';
% Each row verified by reading the cited file:line before transcribing.
% Master §§17-21 lines 675-762; REV3 lines 68,224,437-449,550,623-637,776,829;
% Generator Data_South.pdf pp.6-7 via extractFileText.
rows = {
    'GIS-Q0-breaker', 'Main GIS breaker Q0', 'Q0', [M '684'], 'SOURCE-BACKED'
    'GIS-Q1-disconnector', 'Bus disconnector Q1', 'Q1', [M '685'], 'SOURCE-BACKED'

