function [np, nf] = test_phase5b_sensitivity_v2()
%TEST_PHASE5B_SENSITIVITY_V2  Unit checks for phase5b_sensitivity_v2 (Phase-5b Task C11 fix round 1/4, TDD).
%   Hermetic (synthetic 6-row T40 + live C4 pickups via phase5b_pickup, no
%   production CSVs, no production run, no effectiveness recompute).
%   Guards asserted:
%     - 9 rows (6 GEN-51 phase + 3 GEN-51N earth) with 28 locked cols;
%     - scope SENSITIVITY on all rows;
%     - 16k == 15k x 15/16 within 1e-12 on live rows (finite secondaries);
%     - 1600-upstream CTs used (1600 appears, 2000 absent in outputs);
%     - EF TMS 0.15 reflected in EF times (tms==0.15 + phase5_time recompute);
%     - purity: no file I/O in module (source scan);
%     - errors phase5b-prefixed.
%   All errors are 'phase5b'-prefixed.
T = t_case('test_phase5b_sensitivity_v2');
% ---- Stamped v2 devices via live C4 pickup (synthetic anchors, hermetic) ----
Rreg = phase5b_registry();
devs = Rreg.devices;
ids = {devs.device_id};
dGen = devs(strcmp(ids, 'GEN-51'));
dEf = devs(strcmp(ids, 'GEN-51N'));
dHv = devs(strcmp(ids, 'GSUT-HV-51'));
dQ0 = devs(strcmp(ids, 'GIS-Q0-51'));
Pgen = phase5b_pickup(dGen, double(Rreg.gen.Imax_A), 7000);
Pef = phase5b_pickup(dEf, 0, 7.27);
Phv = phase5b_pickup(dHv, 870.7726, 7000);
Pq0 = phase5b_pickup(dQ0, 869.956652, 7000);
devicesProd = devs;
devicesProd(strcmp(ids, 'GEN-51')).pickup_A = Pgen.setting;
devicesProd(strcmp(ids, 'GEN-51')).tms = Pgen.tms;
devicesProd(strcmp(ids, 'GEN-51')).curve = Pgen.curve;
devicesProd(strcmp(ids, 'GEN-51N')).pickup_A = Pef.setting;
devicesProd(strcmp(ids, 'GEN-51N')).tms = Pef.tms;
devicesProd(strcmp(ids, 'GEN-51N')).curve = Pef.curve;
devicesProd(strcmp(ids, 'GSUT-HV-51')).pickup_A = Phv.setting;
devicesProd(strcmp(ids, 'GSUT-HV-51')).tms = Phv.tms;
devicesProd(strcmp(ids, 'GSUT-HV-51')).curve = Phv.curve;
devicesProd(strcmp(ids, 'GIS-Q0-51')).pickup_A = Pq0.setting;
devicesProd(strcmp(ids, 'GIS-Q0-51')).tms = Pq0.tms;
devicesProd(strcmp(ids, 'GIS-Q0-51')).curve = Pq0.curve;
T = T.chk(abs(Pgen.setting - 17170.8) / 17170.8 < 1e-9, 'GEN-51 live pickup 17170.8 A (hermetic anchor)');
T = T.chk(abs(Pef.setting - 5) < 1e-12 && abs(Pef.tms - 0.15) < 1e-12, 'GEN-51N live pickup 5 A TMS 0.15 (hermetic anchor)');
T = T.chk(abs(Phv.setting - 1380) / 1380 < 1e-9, 'GSUT-HV-51 live pickup 1380 A (hermetic anchor)');
% ---- Synthetic T40: 6 rows covering GEN/grid x phase/earth x live/missing ----
loc = {'F1'; 'F1'; 'F2'; 'F3'; 'F4'; 'F5'};
typ = {'LLL'; 'LG'; 'LL'; 'LLL'; 'LG'; 'LLG'};
cs = {'SYN_A'; 'SYN_A'; 'SYN_B'; 'SYN_A'; 'SYN_B'; 'SYN_A'};
Ip = [55049; 8414.12; 31257.3; 41511.9; 7654.31; 9876.54];
Ik = Ip / 1000;
Iseq0 = [NaN; 8414.12 / 3 / 1000; NaN; NaN; NaN; NaN];
legGEN = [55.049; 8.41412; 31.2573; NaN; NaN; NaN];
legHV = [12.345; 12.345; 9.876; NaN; NaN; NaN];
legNER = [NaN; NaN; NaN; NaN; 7654.31 / 3 / 1000; NaN];
T40 = table(loc, typ, cs, Ip, Ik, Iseq0, legGEN, legHV, legNER, ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', ...
    'I_primary_A', 'I_primary_kA', 'Iseq0_kA', ...
    'leg_GEN_kA', 'leg_GSUT_HV_kA', 'leg_NER_earth_kA'});
S = phase5b_sensitivity_v2(T40, devicesProd, Rreg);
T = T.chk(height(S) == 9, 'GEN-scope rows 6 phase + 3 earth = 9');
T = T.chk(width(S) == 28, 'sensitivity 28 locked cols');
T = T.chk(all(strcmp(S.scope, 'SENSITIVITY')), 'scope SENSITIVITY on all rows');
% ---- 16k == 15k x 15/16 within 1e-12 on live rows ----
live = isfinite(S.I_sec_primary_A) & isfinite(S.I_sec_sens_A) & S.I_sec_primary_A ~= 0;
T = T.chk(any(live), 'live secondary rows present for ratio check');
relErr = abs(S.I_sec_sens_A(live) - S.I_sec_primary_A(live) * 15 / 16) ./ abs(S.I_sec_primary_A(live));
T = T.chk(all(relErr < 1e-12), '16k == 15k x 15/16 within 1e-12 on live rows');
% ---- 1600 upstream used; 2000 absent in outputs ----
allReason = strjoin(S.reason, '|');
allProv = strjoin(S.provenance, '|');
allTag = strjoin(S.ct_tag, '|');
combined = [allReason '|' allProv '|' allTag];
T = T.chk(~isempty(strfind(combined, '1600')), '1600-upstream CTs used (1600 appears in outputs)');
T = T.chk(isempty(strfind(combined, '2000')), 'v1 2000 CT absent in outputs (1600-upstream fix)');
T = T.chk(double(devicesProd(strcmp(ids, 'GSUT-HV-51')).ct_ratio) == 1600, 'GSUT-HV-51 device CT is 1600/1 (upstream dial source)');
% ---- EF TMS 0.15 reflected in EF times ----
isEF = strcmp(S.device_id, 'GEN-51N');
T = T.chk(all(S.tms(isEF) == 0.15), 'EF TMS 0.15 on all GEN-51N rows (not registry 0.20)');
IsFixN = 5 / 15000;
efLive = isEF & isfinite(S.I_sec_primary_A) & isfinite(S.t_primary_s);
T = T.chk(any(efLive), 'live EF rows present for time recompute');
ok015 = true;

